mapper.select:
SELECT * FROM payment_outbox_event
WHERE status IN ('PENDING', 'RETRYING') AND next_retry_at <= #{now}
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE payment_outbox_event SET status = 'RETRYING', attempt_count = attempt_count + 1,
  next_retry_at = #{nextRetryAt}, last_error = #{lastError}
WHERE event_id = #{eventId} AND status IN ('PENDING', 'RETRYING')
